import torch


def gen_inputs(ctx, device):
    result = {}
    dtype = getattr(torch, ctx["query__dtype"])
    for name in ("query", "key", "value"):
        result[name] = torch.empty(
            tuple(ctx[f"{name}__shape"]), dtype=dtype, device=device
        ).uniform_(-0.05, 0.05)
    if "attn_mask__shape" in ctx:
        mask_dtype = getattr(torch, ctx["attn_mask__dtype"])
        result["attn_mask"] = torch.empty(
            tuple(ctx["attn_mask__shape"]), dtype=mask_dtype, device=device
        ).uniform_(-0.05, 0.05)
    return result


def _sdpa(query, key, value, attn_mask, dropout_p, is_causal, dropout_mask, scale, enable_gqa, work_dtype):
    q = query.to(work_dtype)
    k = key.to(work_dtype)
    v = value.to(work_dtype)
    if scale is None:
        scale = q.shape[-1] ** -0.5
    if enable_gqa and k.shape[-3] != q.shape[-3]:
        n_rep = q.shape[-3] // k.shape[-3]
        k = k.repeat_interleave(n_rep, dim=-3)
        v = v.repeat_interleave(n_rep, dim=-3)
    attn = torch.matmul(q, k.transpose(-2, -1)) * float(scale)
    if is_causal:
        L, S = q.shape[-2], k.shape[-2]
        causal = torch.ones(L, S, dtype=torch.bool, device=query.device).tril()
        attn = attn.masked_fill(~causal, float("-inf"))
    if attn_mask is not None:
        attn = attn + attn_mask.to(work_dtype)
    attn = torch.softmax(attn, dim=-1)
    if dropout_p > 0.0:
        if dropout_mask is not None:
            attn = attn.masked_fill(~dropout_mask.to(torch.bool), 0.0)
            attn = attn / (1.0 - dropout_p)
        else:
            attn = torch.nn.functional.dropout(attn, p=dropout_p, training=True)
    output = torch.matmul(attn, v)
    return (output.to(query.dtype), attn.to(query.dtype))


def run(query, key, value, attn_mask, dropout_p, is_causal, dropout_mask, scale, enable_gqa):
    return _sdpa(query, key, value, attn_mask, dropout_p, is_causal, dropout_mask, scale, enable_gqa, query.dtype)


def run_correctness(query, key, value, attn_mask, dropout_p, is_causal, dropout_mask, scale, enable_gqa):
    return _sdpa(query, key, value, attn_mask, dropout_p, is_causal, dropout_mask, scale, enable_gqa, torch.float64)
